import csv, io, json, os, sys
from datetime import datetime, timedelta, timezone


def parse_offset(s):
    sign = -1 if s[0] == '-' else 1
    h, m = s[1:].split(':')
    return timezone(sign * timedelta(hours=int(h), minutes=int(m)))


def parse_time(s, meta):
    if meta.get('submitted_format') == 'local':
        dt = datetime.strptime(s, '%Y-%m-%d %H:%M:%S')
        return dt.replace(tzinfo=parse_offset(meta['utc_offset']))
    s = s.strip()
    if s.endswith('Z') or s.endswith('z'):
        s = s[:-1] + '+00:00'
    return datetime.fromisoformat(s)


def parse_duration(s, meta):
    if meta.get('duration_format') == 'clock':
        sec = 0
        for p in s.split(':'):
            sec = sec * 60 + int(p)
        return sec
    return int(float(s))


def read_exports(d):
    rows = []
    ed = os.path.join(d, 'exports')
    if not os.path.isdir(ed):
        return rows
    for name in sorted(os.listdir(ed)):
        p = os.path.join(ed, name)
        if not name.endswith('.csv') or not os.path.isfile(p):
            continue
        with open(p, 'rb') as f:
            text = f.read().decode('utf-8-sig')
        first = text.replace('\r\n', '\n').replace('\r', '\n').split('\n', 1)[0]
        delim = [c for c in (',', ';', '\t') if c in first]
        delim = delim[0] if delim else ','
        rdr = csv.reader(io.StringIO(text, newline=''), delimiter=delim, quotechar='"')
        header = None
        for rec in rdr:
            if header is None:
                if not rec:
                    continue
                header = [h.strip() for h in rec]
                continue
            cells = [c.strip() for c in rec]
            if not any(cells):
                continue
            row = {}
            for i, h in enumerate(header):
                v = cells[i] if i < len(cells) else ''
                row[h] = v if v != '' else None
            rows.append(row)
    return rows


def to_code(v, recode):
    if recode is not None:
        r = recode[v]
        return int(r)
    return int(v)


def read_answer(q, entry, row, ref_year):
    t = q['type']
    missing = {o['code'] for o in q.get('options', []) if o.get('missing')}
    recode = entry.get('recode')
    if t == 'single':
        v = row.get(entry['column'])
        if v is None:
            return None
        c = to_code(v, recode)
        return None if c in missing else c
    if t == 'age':
        v = row.get(entry['column'])
        if v is None:
            return None
        src = entry.get('source')
        if src == 'band':
            c = to_code(v, recode)
            return c
        age = int(float(v))
        if src == 'birth_year':
            age = ref_year - age
        for b in q['bands']:
            if b['min'] <= age <= b['max']:
                return b['code']
        return None
    # multi
    chosen = set()
    if 'columns' in entry:
        for code, col in entry['columns'].items():
            if row.get(col) == '1':
                chosen.add(int(code))
    else:
        v = row.get(entry['column'])
        if v is not None:
            for e in v.split(entry['separator']):
                e = e.strip()
                if e == '':
                    continue
                chosen.add(to_code(e, recode))
    excl = {o['code'] for o in q['options'] if o.get('exclusive')}
    if chosen & excl:
        if chosen - excl:
            chosen -= excl
        elif len(chosen) >= 2:
            chosen = set()
    chosen -= missing
    return frozenset(chosen) if chosen else None


def rnd(x):
    return None if x is None else round(x + 0.0, 2)


def main(indir, outfile):
    cb = json.load(open(os.path.join(indir, 'codebook.json'), encoding='utf-8'))
    wt = json.load(open(os.path.join(indir, 'weighting.json'), encoding='utf-8'))
    plan = json.load(open(os.path.join(indir, 'tables.json'), encoding='utf-8'))
    versions = cb['versions']
    vkeys = list(versions)
    stats = {v: dict(version=v, rows=0, duplicates=0, short_partials=0,
                     speeders=0, complete=0, partial=0) for v in vkeys}
    ref_year = int(cb['reference_date'][:4])

    recs = []
    for row in read_exports(indir):
        v = row.get('form_version')
        meta = versions[v]['meta']
        stats[v]['rows'] += 1
        rid = row.get(meta['id'])
        comp = row.get(meta['status']) == meta['complete']
        t = parse_time(row[meta['submitted']], meta)
        lp = row.get(meta['last_page'])
        recs.append(dict(v=v, row=row, id=rid, complete=comp, t=t,
                         dur=parse_duration(row[meta['duration']], meta) if (comp and row.get(meta['duration'])) else None,
                         lp=int(lp) if lp is not None else 0))
    best = {}
    for r in recs:
        b = best.get(r['id'])
        if b is None or (r['complete'], r['t']) > (b['complete'], b['t']):
            if b is not None:
                stats[b['v']]['duplicates'] += 1
            best[r['id']] = r
        else:
            stats[r['v']]['duplicates'] += 1
    kept = []
    for r in recs:
        if best[r['id']] is not r:
            continue
        if not r['complete'] and r['lp'] < cb['partial_min_page']:
            stats[r['v']]['short_partials'] += 1
            continue
        kept.append(r)
    med = {}
    for v in vkeys:
        ds = sorted(r['dur'] for r in kept if r['v'] == v and r['complete'])
        n = len(ds)
        if n:
            med[v] = ds[n // 2] if n % 2 else (ds[n // 2 - 1] + ds[n // 2]) / 2
    final = []
    for r in kept:
        if r['complete'] and r['dur'] * 5 < med[r['v']] * 2:
            stats[r['v']]['speeders'] += 1
            continue
        final.append(r)
    for r in final:
        stats[r['v']]['complete' if r['complete'] else 'partial'] += 1

    qs = {q['id']: q for q in cb['questions']}
    # answers
    for r in final:
        ans = {}
        asked = {}
        for q in cb['questions']:
            e = q['versions'].get(r['v'])
            ok = e is not None and (r['complete'] or e['page'] <= r['lp'])
            if ok and q.get('ask_if'):
                c = q['ask_if']
                a = ans.get(c['question'])
                if a is None:
                    ok = False
                else:
                    codes = set(c['codes'])
                    ok = bool(codes & a) if isinstance(a, frozenset) else a in codes
            asked[q['id']] = ok
            ans[q['id']] = read_answer(q, e, r['row'], ref_year) if ok else None
        r['ans'] = ans

    n = len(final)
    w = [1.0] * n
    if n:
        dims = []
        for d in wt['dimensions']:
            qid = d['question']
            present = {r['ans'][qid] for r in final if r['ans'][qid] is not None}
            tg = {int(k): float(v) for k, v in d['targets'].items() if int(k) in present}
            tot = sum(tg.values())
            if not tg or tot <= 0:
                continue
            share = {k: v / tot for k, v in tg.items()}
            cats = [r['ans'][qid] if r['ans'][qid] in share else None for r in final]
            dims.append((share, cats))
        for _ in range(wt['max_iterations']):
            maxdev = 0.0
            for share, cats in dims:
                T = 0.0
                W = {}
                for i, c in enumerate(cats):
                    if c is not None:
                        T += w[i]
                        W[c] = W.get(c, 0.0) + w[i]
                f = {c: share[c] * T / W[c] for c in W}
                for c in f:
                    maxdev = max(maxdev, abs(f[c] - 1))
                for i, c in enumerate(cats):
                    if c is not None:
                        w[i] *= f[c]
            if maxdev <= wt['tolerance']:
                break
        m = sum(w) / n
        hi, lo = wt['cap'] * m, wt['floor'] * m
        w = [min(max(x, lo), hi) for x in w]
        s = sum(w) / n
        w = [x / s for x in w]

    summary = dict(versions=[stats[v] for v in vkeys], respondents=n)
    if n:
        sw = sum(w)
        summary.update(effective_n=rnd(sw * sw / sum(x * x for x in w)),
                       weight_min=rnd(min(w)), weight_max=rnd(max(w)))
    else:
        summary.update(effective_n=None, weight_min=None, weight_max=None)

    def codes_of(q):
        items = q['bands'] if q['type'] == 'age' else q['options']
        return [o for o in items if not o.get('missing')]

    cols = [('total', None, None)]
    for bq in plan['banner']:
        for o in codes_of(qs[bq]):
            cols.append((f"{bq}:{o['code']}", bq, o['code']))
    tables = []
    for t in plan['tables']:
        q = qs[t['question']]
        qid = q['id']
        opts = codes_of(q)
        out = []
        for cid, bq, bc in cols:
            idx = [i for i, r in enumerate(final)
                   if r['ans'][qid] is not None and (bq is None or r['ans'][bq] == bc)]
            wb = sum(w[i] for i in idx)
            vals = {}
            if not idx:
                for o in opts:
                    vals[str(o['code'])] = None
                for nt in t.get('nets', []):
                    vals[nt['id']] = None
                if t.get('mean'):
                    vals['mean'] = None
                out.append(dict(column=cid, base=0, weighted_base=0, values=vals))
                continue

            def has(a, c):
                return c in a if isinstance(a, frozenset) else a == c
            for o in opts:
                s = sum(w[i] for i in idx if has(final[i]['ans'][qid], o['code']))
                vals[str(o['code'])] = rnd(100 * s / wb)
            for nt in t.get('nets', []):
                s = sum(w[i] for i in idx if any(has(final[i]['ans'][qid], c) for c in nt['codes']))
                vals[nt['id']] = rnd(100 * s / wb)
            if t.get('mean'):
                sc = {o['code']: o['score'] for o in opts}
                s = sum(w[i] * sc[final[i]['ans'][qid]] for i in idx)
                vals['mean'] = rnd(s / wb)
            out.append(dict(column=cid, base=len(idx), weighted_base=rnd(wb), values=vals))
        tables.append(dict(table=t['id'], columns=out))
    with open(outfile, 'w', encoding='utf-8') as f:
        json.dump(dict(survey=cb['survey'], summary=summary, tables=tables), f, indent=1)


if __name__ == '__main__':
    main(sys.argv[1], sys.argv[2])
